const leads = $input.all().map(i => i.json);
const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const count = (arr, key) => arr.reduce((acc, x) => { const k = key(x) || 'Без статусу'; acc[k] = (acc[k] || 0) + 1; return acc; }, {});
const isNew = l => l.Created_Time && new Date(l.Created_Time).getTime() >= weekAgo;
const newLeads = leads.filter(isNew);
const bot = leads.filter(l => l.Lead_Source === 'Chat' && l.Skype_ID);
const scores = bot.map(l => Number(l.score_AI)).filter(n => !isNaN(n));
const avg = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
const qualified = bot.filter(l => l.Lead_Status === 'Pre-Qualified').length;
return [{ json: {
  period: `${new Date(weekAgo).toISOString().slice(0, 10)} — ${new Date().toISOString().slice(0, 10)}`,
  total_leads: leads.length,
  new_leads_count: newLeads.length,
  by_stage: count(leads, l => l.Lead_Status),
  by_owner: count(leads, l => l.Owner && l.Owner.name),
  by_source: count(leads, l => l.Lead_Source),
  chatbot_leads: bot.length,
  chatbot_avg_score: avg,
  chatbot_qualified_rate: bot.length ? Math.round(qualified / bot.length * 100) : 0,
  new_leads: newLeads.map(l => ({ name: [l.First_Name, l.Last_Name].filter(Boolean).join(' '), company: l.Company, status: l.Lead_Status, score: l.score_AI, owner: l.Owner && l.Owner.name, objections: l.AI_Objections, next_action: l.AI_Next_Action }))
} }];

const m = $('Метрики воронки (Code)').first().json;
const rows = $('Google Sheets · аналіз діалогів (WF2)').all().map(i => i.json).filter(r => r['Lead ID']);
const analysis = rows.map(r => ({
  channel: 'chat', client: r['Клієнт'], company: r['Компанія'], score: r['Score'], status: r['Статус ліда'],
  rating: r['Оцінка діалогу (1-10)'], agent_errors: r['Помилки агента'], client_problem: r['Проблема клієнта'],
  objections: r['Заперечення'], success_pattern: r['Успішний патерн'], prompt_fix: r['Рекомендація для промпту']
}));
const calls = $input.all().map(i => i.json).filter(r => r['Call ID']).map(r => ({
  channel: 'voice', call_date: r['Дата дзвінка'], duration_sec: r['Тривалість, с'], lead_id: r['Lead ID'], score: r['Score'], status: r['Статус ліда'],
  rating: r['Оцінка розмови (1-10)'], agent_errors: r['Помилки агента'], client_problem: r['Проблема клієнта'],
  objections: r['Заперечення'], success_pattern: r['Успішний патерн'], prompt_fix: r['Рекомендація для промпту']
}));
const all = analysis.concat(calls);
const ratings = all.map(a => Number(a.rating)).filter(n => !isNaN(n) && n > 0);
return [{ json: { metrics: m, dialog_analysis: analysis, call_analysis: calls, analysed_dialogs: analysis.length, analysed_calls: calls.length, avg_dialog_rating: ratings.length ? +(ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(1) : null } }];

