const r = $input.first().json.output;
const d = $('Дані для AI (CRM + Sheets)').first().json;
const m = d.metrics;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const stages = Object.entries(m.by_stage).map(([k, v]) => `${esc(k)}: ${v}`).join(' · ');
const list = (arr, icon) => (arr || []).map(x => `${icon} ${esc(x)}`).join('
');
const mgr = (r.managers || []).map(x => `👤 <b>${esc(x.name)}</b> (${x.leads}): ${esc(x.assessment)}
   → ${esc(x.action)}`).join('
');
let text = `📊 <b>GrowthLab · тижневий звіт CEO</b>
<i>${esc(m.period)}</i>

` +
  `<b>Цифри тижня</b>
Лідів у CRM: <b>${m.total_leads}</b> · нових за тиждень: <b>${m.new_leads_count}</b>
Від AI-чатбота: <b>${m.chatbot_leads}</b> · середній BANT score: <b>${m.chatbot_avg_score}</b> · Pre-Qualified: <b>${m.chatbot_qualified_rate}%</b>
Якість розмов: <b>${d.avg_dialog_rating ?? '—'}/10</b> (чат ${d.analysed_dialogs} · голос ${d.analysed_calls || 0})
Статуси: ${stages}

` +
  `<b>Головне</b>
${esc(r.summary)}

<b>🚧 Вузьке місце</b>
${esc(r.bottleneck)}

<b>⚠️ Проблеми</b>
${list(r.problems, '•')}

<b>👥 Менеджери</b>
${mgr}

<b>✅ Рекомендації на тиждень</b>
${list(r.recommendations, '→')}`;
if (text.length > 4000) text = text.slice(0, 3990) + '…';
return [{ json: { text } }];
